router = APIRouter()

@router.get("/monthly")
def get_monthly_report(
    year: int, 
    month: int, 
    db: Session = Depends(get_db), 
    current_user: models.User = Depends(dependencies.get_current_user)
) -> Dict:
    # Filter by user_id and date range
    from datetime import date
    from sqlalchemy import func

    start_date = date(year, month, 1)
    if month == 12:
        end_date = date(year + 1, 1, 1)
    else:
        end_date = date(year, month + 1, 1)

    expenses = db.query(
        models.Expense.category,
        func.sum(models.Expense.amount).label('total')
    ).filter(
        models.Expense.user_id == current_user.id,
        models.Expense.date >= start_date,
        models.Expense.date < end_date
    ).group_by(models.Expense.category).all()

    total = sum(expense.total for expense in expenses)

    return {
        "period": f"{year}-{month:02d}",
        "total": total,
        "expenses": [{"category": e.category, "total": e.total} for e in expenses]
    }

@router.get("/category")
def get_category_report(
    db: Session = Depends(get_db), 
    current_user: models.User = Depends(dependencies.get_current_user)
) -> Dict:
    from sqlalchemy import func

    result = db.query(
        models.Expense.category,
        func.sum(models.Expense.amount).label('total')
    ).filter(models.Expense.user_id == current_user.id)\
     .group_by(models.Expense.category).all()

    breakdown = {item.category: float(item.total) for item in result}

    return {
        "user_id": current_user.id,
        "breakdown": breakdown
    }

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from '../services/api';

const AddExpense = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    amount: '',
    category: 'Food',
    date: '', // Will be set to today in useEffect
    notes: ''
  });

  useEffect(() => {
    // Set default date to today
    const today = new Date().toISOString().split('T')[0];
    setFormData(prev => ({ ...prev, date: today }));
  }, []);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('/api/expenses', formData);
      navigate('/expenses');
    } catch (error) {
      console.error('Error creating expense:', error);
    }
  };

  const categories = ['Food', 'Transport', 'Utilities', 'Entertainment', 'Health'];

  return (
    <div className="max-w-md mx-auto mt-10 p-6 bg-white rounded-lg shadow-md">
      <h2 className="text-2xl font-bold mb-6">Add New Expense</h2>
      <form onSubmit={handleSubmit}>
        <div className="mb-4">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="amount">
            Amount
          </label>
          <input
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700"
            id="amount"
            name="amount"
            type="number"
            step="0.01"
            placeholder="0.00"
            value={formData.amount}
            onChange={handleChange}
            required
          />
        </div>
        <div className="mb-4">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="category">
            Category
          </label>
          <select
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700"
            id="category"
            name="category"
            value={formData.category}
            onChange={handleChange}
            required
          >
            {categories.map(cat => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
        </div>
        <div className="mb-4">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="date">
            Date
          </label>
          <input
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700"
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            required
          />
        </div>
        <div className="mb-6">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="notes">
            Notes
          </label>
          <textarea
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700"
            id="notes"
            name="notes"
            rows="3"
            placeholder="Add any notes..."
            value={formData.notes}
            onChange={handleChange}
          ></textarea>
        </div>
        <div className="flex items-center justify-between">
          <button
            className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
            type="submit"
          >
            Save Expense
          </button>
        </div>
      </form>
    </div>
  );
};

export default AddExpense;
